'use strict';

/**
* LAPACK routine to compute row and column scale factors intended to equilibrate a matrix `A` and reduce its condition number (using the base of the machine as the scaling restriction).
*
* @module @stdlib/lapack/base/dgeequb
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dgeequb = require( '@stdlib/lapack/base/dgeequb' );
*
* var A = new Float64Array( [ 1.0, 0.0, 0.0, 4.0 ] );
* var R = new Float64Array( 2 );
* var C = new Float64Array( 2 );
* var out = new Float64Array( 3 );
*
* dgeequb( 'row-major', 2, 2, A, 2, R, C, out );
* // R => <Float64Array>[ 1.0, 0.25 ]
* // C => <Float64Array>[ 1.0, 1.0 ]
* // out => <Float64Array>[ 0.25, 1.0, 4.0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dgeequb = require( '@stdlib/lapack/base/dgeequb' );
*
* var A = new Float64Array( [ 1.0, 0.0, 0.0, 4.0 ] );
* var R = new Float64Array( 2 );
* var C = new Float64Array( 2 );
* var out = new Float64Array( 3 );
*
* dgeequb.ndarray( 2, 2, A, 2, 1, 0, R, 1, 0, C, 1, 0, out, 1, 0 );
* // R => <Float64Array>[ 1.0, 0.25 ]
* // C => <Float64Array>[ 1.0, 1.0 ]
* // out => <Float64Array>[ 0.25, 1.0, 4.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dgeequb;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dgeequb = main;
} else {
	dgeequb = tmp;
}


// EXPORTS //

module.exports = dgeequb;

// exports: { "ndarray": "dgeequb.ndarray" }
